/// Macro to initialize OBJECT_ATTRIBUTES
#[macro_export]
macro_rules! InitializeObjectAttributes {
    ($p:expr, $n:expr, $a:expr, $r:expr, $s:expr) => {{
        let oa = $p as *mut OBJECT_ATTRIBUTES;
        unsafe {
            (*oa).Length = core::mem::size_of::<OBJECT_ATTRIBUTES>() as ULONG;
            (*oa).RootDirectory = $r;
            (*oa).Attributes = $a;
            (*oa).ObjectName = $n;
            (*oa).SecurityDescriptor = $s;
            (*oa).SecurityQualityOfService = core::ptr::null_mut();
        }
    }};
}

