// =============================================================================
// SysWhispers3 Runtime - Syscall Resolution
// =============================================================================

/// Hash seed for syscall name hashing
pub const SW3_SEED: u32 = 0xB8A54425;

/// Maximum number of syscall entries
const SW3_MAX_ENTRIES: usize = 600;

/// Syscall entry containing hash, address, and syscall instruction address
#[repr(C)]
#[derive(Copy, Clone, Default)]
struct SW3SyscallEntry {
    hash: u32,
    address: u32,
    syscall_address: usize,
}

/// Global syscall list
#[repr(C)]
struct SW3SyscallList {
    count: u32,
    entries: [SW3SyscallEntry; SW3_MAX_ENTRIES],
}

static mut SW3_SYSCALL_LIST: SW3SyscallList = SW3SyscallList {
    count: 0,
    entries: [SW3SyscallEntry {
        hash: 0,
        address: 0,
        syscall_address: 0,
    }; SW3_MAX_ENTRIES],
};

// =============================================================================
// PEB Structures for NTDLL Resolution
// =============================================================================

#[repr(C)]
struct SW3PebLdrData {
    reserved1: [u8; 8],
    reserved2: [PVOID; 3],
    in_memory_order_module_list: ListEntry,
}

#[repr(C)]
struct ListEntry {
    flink: *mut ListEntry,
    blink: *mut ListEntry,
}

#[repr(C)]
struct SW3LdrDataTableEntry {
    reserved1: [PVOID; 2],
    in_memory_order_links: ListEntry,
    reserved2: [PVOID; 2],
    dll_base: PVOID,
}

#[repr(C)]
struct SW3Peb {
    reserved1: [u8; 2],
    being_debugged: u8,
    reserved2: [u8; 1],
    reserved3: [PVOID; 2],
    ldr: *mut SW3PebLdrData,
}

// =============================================================================
// PE Structures
// =============================================================================

#[repr(C)]
struct ImageDosHeader {
    e_magic: u16,
    e_cblp: u16,
    e_cp: u16,
    e_crlc: u16,
    e_cparhdr: u16,
    e_minalloc: u16,
    e_maxalloc: u16,
    e_ss: u16,
    e_sp: u16,
    e_csum: u16,
    e_ip: u16,
    e_cs: u16,
    e_lfarlc: u16,
    e_ovno: u16,
    e_res: [u16; 4],
    e_oemid: u16,
    e_oeminfo: u16,
    e_res2: [u16; 10],
    e_lfanew: i32,
}

#[repr(C)]
struct ImageExportDirectory {
    characteristics: u32,
    time_date_stamp: u32,
    major_version: u16,
    minor_version: u16,
    name: u32,
    base: u32,
    number_of_functions: u32,
    number_of_names: u32,
    address_of_functions: u32,
    address_of_names: u32,
    address_of_name_ordinals: u32,
}

// =============================================================================
// Hash Function - ROR8 Algorithm (matches C version exactly)
// =============================================================================

/// Hash syscall name using ROR8 algorithm
/// This must match the C version exactly for compatibility
#[inline]
fn sw3_hash_syscall(name: *const u8) -> u32 {
    let mut hash = SW3_SEED;
    let mut i = 0usize;

    unsafe {
        // Loop while current character is not null
        while *name.add(i) != 0 {
            // Read WORD (2 bytes) at position i
            let b1 = *name.add(i) as u32;
            let b2 = *name.add(i + 1) as u32;
            let partial = b1 | (b2 << 8);
            hash ^= partial.wrapping_add(hash.rotate_right(8));
            i += 1;
        }
    }
    hash
}

// =============================================================================
// PEB Access
// =============================================================================

/// Get PEB pointer for x64
#[cfg(target_arch = "x86_64")]
#[inline]
unsafe fn sw3_get_peb() -> *mut SW3Peb {
    let peb: *mut SW3Peb;
    core::arch::asm!(
        "mov {}, gs:[0x60]",
        out(reg) peb,
        options(nostack, nomem, preserves_flags)
    );
    peb
}

/// Get PEB pointer for x86
#[cfg(target_arch = "x86")]
#[inline]
unsafe fn sw3_get_peb() -> *mut SW3Peb {
    let peb: *mut SW3Peb;
    core::arch::asm!(
        "mov {}, fs:[0x30]",
        out(reg) peb,
        options(nostack, nomem, preserves_flags)
    );
    peb
}

/// Check if running under WoW64 (32-bit process on 64-bit Windows)
#[cfg(target_arch = "x86")]
#[inline]
unsafe fn sw3_is_wow64() -> bool {
    let wow64: u32;
    core::arch::asm!(
        "mov eax, fs:[0xc0]",
        "test eax, eax",
        "setne al",
        "movzx eax, al",
        out("eax") wow64,
        options(nostack, nomem)
    );
    wow64 != 0
}

/// Get WoW64 gate address (Wow32Reserved)
#[cfg(target_arch = "x86")]
#[inline]
unsafe fn sw3_get_wow64_gate() -> PVOID {
    let gate: PVOID;
    core::arch::asm!(
        "mov {}, fs:[0xc0]",
        out(reg) gate,
        options(nostack, nomem, preserves_flags)
    );
    gate
}

/// Find syscall/sysenter instruction address in ntdll
/// Used for jumper modes to bypass hooks
unsafe fn sw3_find_syscall_address(nt_api_address: PVOID) -> PVOID {
    const SEARCH_LIMIT: usize = 512;

    #[cfg(target_arch = "x86_64")]
    const SYSCALL_CODE: [u8; 3] = [0x0f, 0x05, 0xc3]; // syscall; ret
    #[cfg(target_arch = "x86_64")]
    const DISTANCE_TO_SYSCALL: usize = 0x12;

    #[cfg(target_arch = "x86")]
    const SYSCALL_CODE: [u8; 3] = [0x0f, 0x34, 0xc3]; // sysenter; ret
    #[cfg(target_arch = "x86")]
    const DISTANCE_TO_SYSCALL: usize = 0x0f;

    let base = nt_api_address as *const u8;

    // Try direct offset first
    let syscall_addr = base.add(DISTANCE_TO_SYSCALL);
    if core::slice::from_raw_parts(syscall_addr, 3) == SYSCALL_CODE {
        return syscall_addr as PVOID;
    }

    // Search nearby (HalosGate style) - handles hooked functions
    for num_jumps in 1..SEARCH_LIMIT {
        // Try below
        let addr = base.add(DISTANCE_TO_SYSCALL + num_jumps * 0x20);
        if core::slice::from_raw_parts(addr, 3) == SYSCALL_CODE {
            return addr as PVOID;
        }

        // Try above
        if DISTANCE_TO_SYSCALL >= num_jumps * 0x20 {
            let addr = base.add(DISTANCE_TO_SYSCALL - num_jumps * 0x20);
            if core::slice::from_raw_parts(addr, 3) == SYSCALL_CODE {
                return addr as PVOID;
            }
        }
    }

    core::ptr::null_mut()
}

/// Populate syscall list from ntdll exports
/// This parses the PEB to find ntdll and extracts all Zw* functions
unsafe fn sw3_populate_syscall_list() -> bool {
    // Return early if already populated
    if SW3_SYSCALL_LIST.count > 0 {
        return true;
    }

    let peb = sw3_get_peb();
    if peb.is_null() {
        return false;
    }

    let ldr = (*peb).ldr;
    if ldr.is_null() {
        return false;
    }

    // Walk the module list to find ntdll
    let list_head = &(*ldr).in_memory_order_module_list as *const ListEntry;
    let mut current = (*list_head).flink;

    while !core::ptr::eq(current, list_head) {
        // Get LDR_DATA_TABLE_ENTRY from list entry
        #[cfg(target_arch = "x86_64")]
        let entry = (current as *const u8).sub(0x10) as *const SW3LdrDataTableEntry;
        #[cfg(target_arch = "x86")]
        let entry = (current as *const u8).sub(0x08) as *const SW3LdrDataTableEntry;

        let dll_base = (*entry).dll_base;

        if dll_base.is_null() {
            current = (*current).flink;
            continue;
        }

        // Check DOS header
        let dos_header = dll_base as *const ImageDosHeader;
        if (*dos_header).e_magic != 0x5A4D {
            // "MZ"
            current = (*current).flink;
            continue;
        }

        // Get NT headers and export directory
        let nt_headers = (dll_base as *const u8).add((*dos_header).e_lfanew as usize);

        #[cfg(target_arch = "x86_64")]
        let export_dir_rva = *(nt_headers.add(0x88) as *const u32);
        #[cfg(target_arch = "x86")]
        let export_dir_rva = *(nt_headers.add(0x78) as *const u32);

        if export_dir_rva == 0 {
            current = (*current).flink;
            continue;
        }

        let export_dir =
            (dll_base as *const u8).add(export_dir_rva as usize) as *const ImageExportDirectory;
        let dll_name = (dll_base as *const u8).add((*export_dir).name as usize);

        // Check for "ntdll" (case insensitive)
        let name_check = *(dll_name as *const u32) | 0x20202020;
        if name_check != 0x6C64746E {
            // "ntdl"
            current = (*current).flink;
            continue;
        }

        // Found ntdll - enumerate Zw* functions
        let num_names = (*export_dir).number_of_names;
        let names =
            (dll_base as *const u8).add((*export_dir).address_of_names as usize) as *const u32;
        let functions =
            (dll_base as *const u8).add((*export_dir).address_of_functions as usize) as *const u32;
        let ordinals = (dll_base as *const u8).add((*export_dir).address_of_name_ordinals as usize)
            as *const u16;

        let mut count = 0u32;

        // Iterate backwards through names (matches C version)
        let mut i = num_names;
        while i > 0 {
            i -= 1;
            let name_rva = *names.add(i as usize);
            let func_name = (dll_base as *const u8).add(name_rva as usize);

            // Check if starts with "Zw"
            if *func_name == b'Z' && *func_name.add(1) == b'w' {
                let ordinal = *ordinals.add(i as usize);
                let func_rva = *functions.add(ordinal as usize);

                SW3_SYSCALL_LIST.entries[count as usize].hash = sw3_hash_syscall(func_name);
                SW3_SYSCALL_LIST.entries[count as usize].address = func_rva;

                // For jumper modes, find the syscall instruction address
                let func_addr = (dll_base as *const u8).add(func_rva as usize) as PVOID;
                SW3_SYSCALL_LIST.entries[count as usize].syscall_address =
                    sw3_find_syscall_address(func_addr) as usize;

                count += 1;
                if count as usize >= SW3_MAX_ENTRIES {
                    break;
                }
            }
        }

        SW3_SYSCALL_LIST.count = count;

        // Sort by address (bubble sort - matches C version)
        for ii in 0..(count as usize).saturating_sub(1) {
            for j in 0..(count as usize) - ii - 1 {
                if SW3_SYSCALL_LIST.entries[j].address > SW3_SYSCALL_LIST.entries[j + 1].address {
                    SW3_SYSCALL_LIST.entries.swap(j, j + 1);
                }
            }
        }

        return true;
    }

    false
}

/// Get syscall number by function hash
/// Returns 0xFFFFFFFF on failure
#[inline(never)]
pub unsafe fn sw3_get_syscall_number(function_hash: u32) -> u32 {
    if !sw3_populate_syscall_list() {
        return 0xFFFFFFFF;
    }

    for i in 0..SW3_SYSCALL_LIST.count as usize {
        if SW3_SYSCALL_LIST.entries[i].hash == function_hash {
            return i as u32;
        }
    }

    0xFFFFFFFF
}

/// Debug function to get syscall list count
#[inline(never)]
pub unsafe fn sw3_debug_get_count() -> u32 {
    sw3_populate_syscall_list();
    SW3_SYSCALL_LIST.count
}

/// Debug function to get hash at index
#[inline(never)]
pub unsafe fn sw3_debug_get_hash(index: usize) -> u32 {
    if index < SW3_SYSCALL_LIST.count as usize {
        SW3_SYSCALL_LIST.entries[index].hash
    } else {
        0
    }
}

/// Debug function to get syscall address at index
#[inline(never)]
pub unsafe fn sw3_debug_get_syscall_addr(index: usize) -> PVOID {
    if index < SW3_SYSCALL_LIST.count as usize {
        SW3_SYSCALL_LIST.entries[index].syscall_address as PVOID
    } else {
        core::ptr::null_mut()
    }
}

/// Get syscall address for jumper mode
#[inline(never)]
pub unsafe fn sw3_get_syscall_address(function_hash: u32) -> PVOID {
    if !sw3_populate_syscall_list() {
        return core::ptr::null_mut();
    }

    for i in 0..SW3_SYSCALL_LIST.count as usize {
        if SW3_SYSCALL_LIST.entries[i].hash == function_hash {
            let addr = SW3_SYSCALL_LIST.entries[i].syscall_address;
            if addr != 0 {
                return addr as PVOID;
            }
            // Syscall address is null (function may be hooked), find another one
            break;
        }
    }

    // Fallback: find any valid syscall address
    for i in 0..SW3_SYSCALL_LIST.count as usize {
        let addr = SW3_SYSCALL_LIST.entries[i].syscall_address;
        if addr != 0 {
            return addr as PVOID;
        }
    }

    core::ptr::null_mut()
}

/// Get random syscall address for jumper_randomized mode
/// Returns a syscall address from a different function to spoof return address
#[inline(never)]
pub unsafe fn sw3_get_random_syscall_address(function_hash: u32) -> PVOID {
    if !sw3_populate_syscall_list() {
        return core::ptr::null_mut();
    }

    // Use function hash as seed for deterministic but varied selection
    let mut index = (function_hash as usize) % (SW3_SYSCALL_LIST.count as usize);

    // Make sure we don't return our own syscall address and that it's valid
    let mut attempts = 0;
    while (SW3_SYSCALL_LIST.entries[index].hash == function_hash
        || SW3_SYSCALL_LIST.entries[index].syscall_address == 0)
        && attempts < SW3_SYSCALL_LIST.count
    {
        index = (index + 1) % (SW3_SYSCALL_LIST.count as usize);
        attempts += 1;
    }

    SW3_SYSCALL_LIST.entries[index].syscall_address as PVOID
}

