/// NtAcceptConnectPort syscall
///
/// Hash: 0x2E4827D6
#[cfg(target_arch = "x86_64")]
#[unsafe(naked)]
pub unsafe extern "C" fn nt_accept_connect_port(
    server_port_handle: *mut HANDLE,
    alternative_receive_port_handle: ULONG,
    connection_reply: PPORT_MESSAGE,
    accept_connection: BOOLEAN,
    server_shared_memory: PPORT_SECTION_WRITE,
    client_shared_memory: PPORT_SECTION_READ,
) -> NTSTATUS {
    // Naked function - exact replica of C/ASM pattern:
    // 1. Save params to shadow space (caller allocated 0x20 bytes)
    // 2. Get syscall address -> r11
    // 3. Get syscall number -> eax
    // 4. Restore params
    // 5. mov r10, rcx
    // 6. jmp r11 (returns to our caller)
    core::arch::naked_asm!(
        // Save incoming registers to shadow space (caller allocated)
        "mov [rsp + 0x08], rcx",
        "mov [rsp + 0x10], rdx",
        "mov [rsp + 0x18], r8",
        "mov [rsp + 0x20], r9",

        // Allocate shadow space for our calls
        "sub rsp, 0x28",

        // Get syscall address: sw3_get_random_syscall_address(hash) -> rax
        "mov ecx, 0X2E4827D6",
        "call {get_addr}",
        "mov r11, rax",  // Save syscall address in r11

        // Get syscall number: sw3_get_syscall_number(hash) -> eax
        "mov ecx, 0X2E4827D6",
        "call {get_num}",

        // Restore stack
        "add rsp, 0x28",

        // Restore registers from shadow space
        "mov rcx, [rsp + 0x08]",
        "mov rdx, [rsp + 0x10]",
        "mov r8, [rsp + 0x18]",
        "mov r9, [rsp + 0x20]",

        // Syscall convention: first param in r10 (rcx is clobbered by syscall)
        "mov r10, rcx",

        // Jump to syscall;ret in ntdll - this returns directly to our caller
        "jmp r11",

        get_addr = sym sw3_get_random_syscall_address,
        get_num = sym sw3_get_syscall_number,
    )
}

/// NtAcceptConnectPort syscall (x86/WoW64)
///
/// Hash: 0x2E4827D6
#[cfg(target_arch = "x86")]
#[inline(never)]
pub unsafe fn nt_accept_connect_port(
    server_port_handle: *mut HANDLE,
    alternative_receive_port_handle: ULONG,
    connection_reply: PPORT_MESSAGE,
    accept_connection: BOOLEAN,
    server_shared_memory: PPORT_SECTION_WRITE,
    client_shared_memory: PPORT_SECTION_READ,
) -> NTSTATUS {
    let syscall_num = sw3_get_syscall_number(0x2E4827D6_u32);
    let syscall_addr = sw3_get_random_syscall_address(0x2E4827D6_u32);
    let status: i32;

    core::arch::asm!(
        "push {p5}",
        "push {p4}",
        "push {p3}",
        "push {p2}",
        "push {p1}",
        "push {p0}",
        "mov eax, {num}",
        "mov edx, esp",
        "call {addr}",
        "add esp, 24",
        num = in(reg) syscall_num,
        addr = in(reg) syscall_addr as u32,
        p0 = in(reg) server_port_handle as u32,
        p1 = in(reg) alternative_receive_port_handle as u32,
        p2 = in(reg) connection_reply as u32,
        p3 = in(reg) accept_connection as u32,
        p4 = in(reg) server_shared_memory as u32,
        p5 = in(reg) client_shared_memory as u32,
        lateout("eax") status,
        clobber_abi("C"),
    );
    status
}

/// NtAccessCheck syscall
