/// Initialize UNICODE_STRING from a wide string slice
///
/// # Safety
/// The buffer must remain valid for the lifetime of the UNICODE_STRING
#[inline]
pub unsafe fn RtlInitUnicodeString(dest: *mut UNICODE_STRING, src: *const u16) {
    if src.is_null() {
        (*dest).Length = 0;
        (*dest).MaximumLength = 0;
        (*dest).Buffer = core::ptr::null_mut();
    } else {
        let mut len = 0u16;
        let mut p = src;
        while *p != 0 {
            len += 1;
            p = p.add(1);
        }
        let byte_len = len * 2;
        (*dest).Length = byte_len;
        (*dest).MaximumLength = byte_len + 2;
        (*dest).Buffer = src as *mut u16;
    }
}

/// Calculate hash for a function name (for manual lookups)
/// Name should start with "Zw" (e.g., "ZwQuerySystemTime")
/// This matches the hash algorithm used by the runtime
#[inline]
pub fn sw3_hash_function_name(name: &str) -> u32 {
    let mut hash = SW3_SEED;
    let bytes = name.as_bytes();
    let len = bytes.len();
    let mut i = 0;

    // Process pairs of bytes (including implicit null terminator)
    while i < len {
        let b1 = bytes[i] as u32;
        let b2 = if i + 1 < len { bytes[i + 1] as u32 } else { 0 };

        if b2 == 0 && i + 1 >= len {
            // Last character paired with null terminator
            let partial = b1;
            hash ^= partial.wrapping_add(hash.rotate_right(8));
            break;
        }

        let partial = b1 | (b2 << 8);
        hash ^= partial.wrapping_add(hash.rotate_right(8));
        i += 1;
    }
    hash
}
